import csv
import datetime as dt
from pathlib import Path
import requests

STATIONS_PATH = Path('/root/data/michigan_stations.txt')
OUTPUT_PATH = Path('/root/output/flood_results.csv')

START_DATE = dt.date(2025, 4, 1)
END_DATE = dt.date(2025, 4, 7)

stations = [line.strip() for line in STATIONS_PATH.read_text().splitlines() if line.strip()]

session = requests.Session()

# Cache for ratings by LID
ratings_cache = {}

def fetch_ratings(lid):
    if lid in ratings_cache:
        return ratings_cache[lid]
    url = f"https://api.water.noaa.gov/nwps/v1/gauges/{lid}/ratings"
    resp = session.get(url, params={'onlyTenths': 'true'}, timeout=30)
    if resp.status_code != 200:
        ratings_cache[lid] = []
        return []
    data = resp.json()
    pts = data.get('data') or []
    if not pts:
        # Try without onlyTenths in case filtered data is empty
        resp = session.get(url, timeout=30)
        if resp.status_code == 200:
            data = resp.json()
            pts = data.get('data') or []
    ratings_cache[lid] = pts
    return pts


def interpolate_flow(rating_points, stage):
    # rating_points: list of dicts with 'stage' and 'flow'
    if not rating_points:
        return None
    pts = sorted(rating_points, key=lambda x: x['stage'])
    # clamp to range
    if stage <= pts[0]['stage']:
        return float(pts[0]['flow'])
    if stage >= pts[-1]['stage']:
        return float(pts[-1]['flow'])
    for i in range(len(pts) - 1):
        a = pts[i]
        b = pts[i + 1]
        if a['stage'] <= stage <= b['stage']:
            if b['stage'] == a['stage']:
                return float(a['flow'])
            # linear interpolation
            return float(a['flow'] + (b['flow'] - a['flow']) * (stage - a['stage']) / (b['stage'] - a['stage']))
    return None

thresholds = {}  # station -> dict(type='flow'|'stage', value=float)

for sid in stations:
    url = f"https://api.water.noaa.gov/nwps/v1/gauges/{sid}"
    resp = session.get(url, timeout=20)
    if resp.status_code != 200:
        continue
    data = resp.json()
    lid = data.get('lid')
    categories = (data.get('flood') or {}).get('categories') or {}
    minor = categories.get('minor') or {}
    flow = minor.get('flow')
    stage = minor.get('stage')

    # Prefer direct flow threshold if valid
    if isinstance(flow, (int, float)) and flow > 0 and flow != -9999:
        thresholds[sid] = {'type': 'flow', 'value': float(flow)}
        continue

    # Try to convert stage to flow via ratings
    if isinstance(stage, (int, float)) and stage > 0 and stage != -9999 and lid:
        rating_points = fetch_ratings(lid)
        flow_from_stage = interpolate_flow(rating_points, float(stage))
        if flow_from_stage is not None and flow_from_stage > 0:
            thresholds[sid] = {'type': 'flow', 'value': float(flow_from_stage)}
            continue
        # If ratings missing, fall back to stage threshold
        thresholds[sid] = {'type': 'stage', 'value': float(stage)}
        continue

# Helper to fetch USGS daily values for a parameter and list of stations
USGS_DV = 'https://waterservices.usgs.gov/nwis/dv/'

def fetch_dv(param_cd, station_ids):
    if not station_ids:
        return {}
    sites = ','.join(station_ids)
    params = {
        'format': 'json',
        'sites': sites,
        'parameterCd': param_cd,
        'startDT': START_DATE.isoformat(),
        'endDT': END_DATE.isoformat(),
    }
    resp = session.get(USGS_DV, params=params, timeout=60)
    resp.raise_for_status()
    data = resp.json()
    series_list = data.get('value', {}).get('timeSeries', [])
    results = {}
    for ts in series_list:
        site_no = ts.get('sourceInfo', {}).get('siteCode', [{}])[0].get('value')
        if not site_no:
            continue
        values = ts.get('values', [{}])[0].get('value', [])
        site_data = results.setdefault(site_no, {})
        for v in values:
            val = v.get('value')
            if val in (None, ''):
                continue
            try:
                fval = float(val)
            except ValueError:
                continue
            date_str = v.get('dateTime', '')[:10]
            if date_str:
                site_data[date_str] = fval
    return results

# Split stations by threshold type
flow_stations = [sid for sid, t in thresholds.items() if t['type'] == 'flow']
stage_stations = [sid for sid, t in thresholds.items() if t['type'] == 'stage']

flow_data = fetch_dv('00060', flow_stations)
stage_data = fetch_dv('00065', stage_stations)

# Build date range list
num_days = (END_DATE - START_DATE).days + 1
all_dates = [(START_DATE + dt.timedelta(days=i)).isoformat() for i in range(num_days)]

rows = []
for sid, t in thresholds.items():
    if t['type'] == 'flow':
        series = flow_data.get(sid, {})
    else:
        series = stage_data.get(sid, {})
    flood_days = 0
    for d in all_dates:
        val = series.get(d)
        if val is None:
            continue
        if val >= t['value']:
            flood_days += 1
    if flood_days > 0:
        rows.append((sid, flood_days))

rows.sort(key=lambda x: x[0])

OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
with OUTPUT_PATH.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    writer.writerows(rows)

print(f"Wrote {len(rows)} rows to {OUTPUT_PATH}")
